style.css:
/* DISCORD DARK NEON THEME */
/* Stylish compatible - No external imports */

:root {
    --background-primary: #10111c !important;
    --background-secondary: #151625 !important;
    --background-tertiary: #0c0d16 !important;
    --background-floating: #191a2c !important;
    --brand-experiment: #8b5cf6 !important;
    --text-link: #a78bfa !important;
    --background-modifier-hover: #292344 !important;
}

body {
    font-family: Arial, sans-serif !important;
}

[class*="sidebar"] {
    background: #10111c !important;
}

[class*="chat"] {
    background: #131421 !important;
}

[class*="members"] {
    background: #10111c !important;
}

[class*="message"] {
    border-radius: 10px !important;
}

[class*="message"]:hover {
    background: #201c35 !important;
}

[class*="channel"]:hover {
    background: #292344 !important;
    border-radius: 8px !important;
}

button {
    transition: all 0.2s ease !important;
}

button:hover {
    filter: brightness(1.2);
}

::selection {
    background: #8b5cf6 !important;
    color: white !important;
}

::-webkit-scrollbar-thumb {
    background: #7044d4 !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-track {
    background: #10111c !important;
}
